export function permissionsForAppMethod(method: string): readonly ModulePermission[] | null | undefined {
  return Object.hasOwn(APP_METHOD_PERMISSIONS, method) ? APP_METHOD_PERMISSIONS[method] : undefined;
}
export const MODULE_HIGH_RISK_PERMISSIONS: ReadonlySet<ModulePermission> = new Set(["code.execute", "terminal.run", "network", "modules.install"]);
/** Common fail-closed authorization gate for every RPC method. */
export function assertAppMethodPermission(method: string, granted: readonly ModulePermission[]): void {
  const required = permissionsForAppMethod(method);
  if (required === null) throw Error(`方法 ${method} 不可委托给扩展`);
  if (required === undefined) throw Error(`未知方法 ${method}，没有可授权的权限映射`);
  for (const permission of required) {
    if (!granted.includes(permission)) throw Error(`这个扩展没有 ${permission} 权限（调用 ${method} 被拒绝）`);
  }
}
